<?php
namespace Tests\Feature;use App\Models\{Institution,Survey,User};use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class ScientificValidationTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}public function test_idw_holdout_validation_records_mae_and_rmse():void{$u=User::factory()->create();$u->assignRole('Network Admin');$i=Institution::create(['name'=>'T','slug'=>'t']);$c=$i->campuses()->create(['name'=>'M','code'=>'M']);$b=$c->buildings()->create(['name'=>'B','code'=>'B']);$f=$b->floors()->create(['name'=>'G','code'=>'G','level_number'=>0]);$fp=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p','file_path'=>'p','mime_type'=>'image/png','file_size'=>1,'version'=>1]);$s=Survey::create(['floor_id'=>$f->id,'floor_plan_id'=>$fp->id,'created_by'=>$u->id,'name'=>'Validation']);for($n=0;$n<12;$n++){$p=$s->points()->create(['floor_plan_id'=>$fp->id,'captured_by'=>$u->id,'x_normalized'=>.05+($n%4)*.25,'y_normalized'=>.1+intdiv($n,4)*.35,'source_type'=>'measured','collection_method'=>'manual','validation_status'=>'valid','captured_at'=>now()]);$p->measurements()->create(['rssi_dbm'=>-45-$n*2,'source_type'=>'measured','collection_method'=>'manual','is_simulated'=>false,'captured_at'=>now()]);}$this->actingAs($u)->postJson("/api/surveys/{$s->id}/validation",['holdout_percent'=>20,'power'=>2])->assertCreated()->assertJsonPath('status','completed')->assertJsonStructure(['mean_absolute_error','root_mean_square_error','predictions']);$this->assertDatabaseCount('validation_runs',1);}public function test_super_admin_can_run_acceptance_audit():void{$u=User::factory()->create();$u->assignRole('Super Admin');$this->actingAs($u)->postJson('/api/validation/acceptance')->assertCreated()->assertJsonStructure(['status','passed_checks','failed_checks','checks']);}}
